import{c as t,Q as i,j as n,m as e}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Notifikasi Otomatis","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/notifikasi.md","filePath":"panduan/notifikasi.md"}'),r={name:"panduan/notifikasi.md"};function o(s,a,d,l,h,g){return i(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="notifikasi-otomatis" tabindex="-1">Notifikasi Otomatis <a class="header-anchor" href="#notifikasi-otomatis" aria-label="Permalink to &quot;Notifikasi Otomatis&quot;">​</a></h1><p>Eznom mengirim notifikasi pengingat tagihan ke pelanggan secara otomatis via <strong>WhatsApp</strong> (Fonnte) dan/atau <strong>Email</strong>.</p><hr><h2 id="konfigurasi-awal" tabindex="-1">Konfigurasi Awal <a class="header-anchor" href="#konfigurasi-awal" aria-label="Permalink to &quot;Konfigurasi Awal&quot;">​</a></h2><p>Buka <strong>Pengaturan → Notifikasi</strong></p><h3 id="channel-notifikasi" tabindex="-1">Channel Notifikasi <a class="header-anchor" href="#channel-notifikasi" aria-label="Permalink to &quot;Channel Notifikasi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pilihan</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>WhatsApp saja</strong></td><td>Notifikasi hanya via WA</td></tr><tr><td><strong>Email saja</strong></td><td>Notifikasi hanya via email</td></tr><tr><td><strong>WhatsApp &amp; Email</strong></td><td>Keduanya</td></tr></tbody></table><h3 id="whatsapp-via-fonnte" tabindex="-1">WhatsApp via Fonnte <a class="header-anchor" href="#whatsapp-via-fonnte" aria-label="Permalink to &quot;WhatsApp via Fonnte&quot;">​</a></h3><p>Eznom menggunakan <a href="https://fonnte.com" target="_blank" rel="noreferrer">Fonnte</a> sebagai gateway WhatsApp. Daftarkan perangkat WA Anda di Fonnte terlebih dahulu.</p><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Fonnte API Key</strong></td><td>Token dari dashboard Fonnte</td></tr><tr><td><strong>Nomor Pengirim</strong></td><td>Nomor WA yang terdaftar di akun Fonnte (format: 08xxx)</td></tr></tbody></table><p>Klik <strong>Test Kirim</strong> untuk memverifikasi konfigurasi sebelum menyimpan.</p><hr><h2 id="jadwal-pengingat" tabindex="-1">Jadwal Pengingat <a class="header-anchor" href="#jadwal-pengingat" aria-label="Permalink to &quot;Jadwal Pengingat&quot;">​</a></h2><h3 id="pengingat-sebelum-jatuh-tempo-h-n" tabindex="-1">Pengingat Sebelum Jatuh Tempo (H-N) <a class="header-anchor" href="#pengingat-sebelum-jatuh-tempo-h-n" aria-label="Permalink to &quot;Pengingat Sebelum Jatuh Tempo (H-N)&quot;">​</a></h3><p>Centang hari-hari yang Anda inginkan:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>□ H-1  □ H-2  □ H-3  □ H-5  ☑ H-7  □ H-14  □ H-30</span></span></code></pre></div><p>Contoh: centang H-7 dan H-3 → notifikasi dikirim 7 hari sebelum JT, lalu pengingat kedua 3 hari sebelum JT. Setiap kombinasi hanya dikirim <strong>satu kali</strong> per tagihan.</p><h3 id="pengingat-hari-jatuh-tempo-h-0" tabindex="-1">Pengingat Hari Jatuh Tempo (H-0) <a class="header-anchor" href="#pengingat-hari-jatuh-tempo-h-0" aria-label="Permalink to &quot;Pengingat Hari Jatuh Tempo (H-0)&quot;">​</a></h3><p>Selalu aktif — dikirim otomatis pada hari tagihan jatuh tempo. Tidak bisa dinonaktifkan.</p><hr><h2 id="grace-period-isolir" tabindex="-1">Grace Period Isolir <a class="header-anchor" href="#grace-period-isolir" aria-label="Permalink to &quot;Grace Period Isolir&quot;">​</a></h2><p>Tentukan berapa hari setelah jatuh tempo sebelum pelanggan otomatis diisolir:</p><table tabindex="0"><thead><tr><th>Nilai</th><th>Efek</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Isolir langsung pada hari H jatuh tempo (perilaku default)</td></tr><tr><td><strong>3</strong></td><td>Pelanggan diberi waktu 3 hari setelah JT sebelum diisolir</td></tr><tr><td><strong>7</strong></td><td>Grace period 7 hari</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Isolir otomatis hanya berlaku untuk pelanggan yang memiliki opsi <strong>Auto Isolir</strong> diaktifkan di data pelanggan.</p></div><hr><h2 id="notifikasi-tunggakan-berulang" tabindex="-1">Notifikasi Tunggakan Berulang <a class="header-anchor" href="#notifikasi-tunggakan-berulang" aria-label="Permalink to &quot;Notifikasi Tunggakan Berulang&quot;">​</a></h2><p>Kirim pengingat secara berkala ke pelanggan yang sudah melewati jatuh tempo dan belum membayar:</p><table tabindex="0"><thead><tr><th>Nilai</th><th>Efek</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Nonaktif — tidak ada pengingat tunggakan otomatis</td></tr><tr><td><strong>3</strong></td><td>Kirim ulang setiap 3 hari selama masih belum bayar</td></tr><tr><td><strong>7</strong></td><td>Kirim ulang setiap 7 hari</td></tr></tbody></table><hr><h2 id="jadwal-eksekusi-otomatis" tabindex="-1">Jadwal Eksekusi Otomatis <a class="header-anchor" href="#jadwal-eksekusi-otomatis" aria-label="Permalink to &quot;Jadwal Eksekusi Otomatis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Proses</th><th>Waktu</th></tr></thead><tbody><tr><td>Kirim notifikasi pengingat</td><td>Setiap hari <strong>07:00</strong></td></tr><tr><td>Proses isolir otomatis</td><td>Setiap hari <strong>08:00</strong></td></tr><tr><td>Generate tagihan bulanan</td><td>Setiap hari <strong>01:00</strong></td></tr></tbody></table><hr><h2 id="isi-pesan-notifikasi" tabindex="-1">Isi Pesan Notifikasi <a class="header-anchor" href="#isi-pesan-notifikasi" aria-label="Permalink to &quot;Isi Pesan Notifikasi&quot;">​</a></h2><p>Pesan yang dikirim ke pelanggan sudah diformat otomatis, berisi:</p><ul><li>Salam + nama pelanggan</li><li>Jumlah tagihan dan tanggal jatuh tempo</li><li>Link pembayaran (jika Midtrans aktif)</li><li>Informasi kontak bisnis Anda (dari pengaturan profil bisnis)</li></ul><hr><h2 id="riwayat-notifikasi" tabindex="-1">Riwayat Notifikasi <a class="header-anchor" href="#riwayat-notifikasi" aria-label="Permalink to &quot;Riwayat Notifikasi&quot;">​</a></h2><p>Riwayat semua notifikasi yang pernah dikirim tersedia di:</p><ul><li><strong>Per pelanggan</strong>: Halaman detail pelanggan → Tab <strong>Notifikasi</strong></li><li><strong>Per router</strong>: Sidebar → <strong>Log Notifikasi</strong></li></ul>',39)])])}const k=t(r,[["render",o]]);export{u as __pageData,k as default};
